/**
 * Two images whose distance is below this threshold may not appear on the same screen.
 * @type {number}
 */
export const SIMILARITY_THRESHOLD = 0.5100;

// --- Stimulus state ---

/**
 * Rank buckets of the distractors, one per gap of the ordering:
 * ['above-1', 'between-1-2', ..., 'between-6-7', 'below-7'].
 * @type {string[]}
 */
export const RANK_BUCKET_NAMES = (() => {
  const n = CONFIG.numItems;
  const names = ['above-1'];
  for (let i = 1; i < n; i++) {
    names.push(`between-${i}-${i + 1}`);
  }
  names.push(`below-${n}`);
  return names;
})();

/**
 * The session's stimuli, set by initStimuliState(). Items are {id, label, image}.
 */
export const stimuliState = {
  /** The seven main items: learning, IWL and arbitrage tests. */
  mainItems: [],
  /** The 16 learning distractors, two per rank bucket. */
  trainingDistractors: [],
  /**
   * The five novel orderings of the ICL test, seven items each, top rank first. No two of them
   * share an item, and one trial shows items of one ordering only.
   */
  iclOrderings: [],
  /** The two end distractors of each novel ordering ([above, below]). */
  iclEndDistractors: [],
  /** The seven items of the single-step and multistep practice blocks. */
  practiceItems: [],
  /** Their two end distractors. */
  practiceEndDistractors: [],
  /** The three items of the query-only practice block, used nowhere else. */
  queryOnlyPracticeItems: [],
  /**
   * The learning distractors by rank bucket, { 'above-1': [id1, id2], ... }; within a bucket
   * the first is the higher.
   * @type {Object<string, string[]>}
   */
  distractorBuckets: {},
  /** Item IDs by role, as saved. */
  imageAssignments: {},
  /** The trained ordering: main-item IDs from highest to lowest. */
  trainedOrdering: [],
};

/** @type {Map<string, {id: string, label: string, image: string}>|null} */
let _idMap = null;

function ensureIdMap() {
  if (!_idMap) {
    _idMap = new Map(ALL_IMAGES.map(s => [s.id, s]));
  }
  return _idMap;
}

// --- Distractors ---

/**
 * A learning distractor of one rank bucket, drawn at random.
 *
 * @param {string} bucketName - e.g. 'between-3-4'.
 * @param {Set<string>} [excludeIds] - IDs already in the chain.
 * @returns {string} Distractor ID.
 */
export function drawRankedDistractor(bucketName, excludeIds) {
  const bucket = stimuliState.distractorBuckets[bucketName];
  const eligible = excludeIds ? bucket.filter(id => !excludeIds.has(id)) : bucket;
  if (eligible.length === 0) {
    throw new Error(`No eligible distractors in bucket ${bucketName}`);
  }
  return randomChoice(eligible);
}

/**
 * Two learning distractors of one rank bucket, for two distractors in one gap; returned in
 * their order within the bucket, higher first.
 *
 * @param {string} bucketName
 * @param {Set<string>} [excludeIds] - IDs already in the chain.
 * @returns {string[]}
 */
export function drawTwoRankedDistractors(bucketName, excludeIds) {
  const bucket = stimuliState.distractorBuckets[bucketName];
  const eligible = excludeIds ? bucket.filter(id => !excludeIds.has(id)) : [...bucket];
  if (eligible.length < 2) {
    throw new Error(`Need 2 distractors in bucket ${bucketName}, only ${eligible.length} available`);
  }
  const shuffled = shuffledCopy(eligible);
  const picked = shuffled.slice(0, 2);
  picked.sort((a, b) => bucket.indexOf(a) - bucket.indexOf(b));
  return picked;
}

/**
 * The rank bucket of a gap: -1 above the first item, g between items g and g + 1 (0-based),
 * N-1 below the last.
 *
 * @param {number} gapIndex - -1 to numItems - 1.
 * @returns {string}
 */
export function getBucketForGap(gapIndex) {
  return RANK_BUCKET_NAMES[gapIndex + 1];
}

/**
 * Assign the learning distractors to the rank buckets at random, N per bucket.
 *
 * @param {string[]} distractorIds
 * @returns {Object<string, string[]>} Bucket name -> distractor IDs, higher first.
 */
function generateDistractorBuckets(distractorIds) {
  const N = CONFIG.distractorsPerRankBucket;
  const shuffled = shuffledCopy(distractorIds);
  const buckets = {};
  for (let b = 0; b < RANK_BUCKET_NAMES.length; b++) {
    buckets[RANK_BUCKET_NAMES[b]] = shuffled.slice(b * N, (b + 1) * N);
  }
  return buckets;
}

// --- Image roles ---

/** Image ID -> index in ALL_IMAGES and SIMILARITY_MATRIX. */
function buildImageIndexMap() {
  const map = new Map();
  for (let i = 0; i < ALL_IMAGES.length; i++) {
    map.set(ALL_IMAGES[i].id, i);
  }
  return map;
}

/**
 * Keep similar images off the same screen by swapping images between role groups.
 *
 * The groups, which together hold every image once: (1) the main items and the learning
 * distractors; (2-6) each novel ordering with its end distractors; (7) the practice items with
 * their end distractors; (8) the query-only practice items.
 *
 * Up to 50 rounds. Each round visits the groups in random order; in a group whose closest pair
 * is below SIMILARITY_THRESHOLD, the second image of that pair is swapped with the first
 * candidate (other groups and their images in random order) that is close to nothing in its new
 * group and leaves nothing close in the candidate's group. The arrangement with the largest
 * smallest distance so far is kept, and restored if the rounds run out with a pair still below
 * the threshold.
 *
 * @returns {number} Number of swaps made.
 */
function ensureGroupDistinctiveness() {
  const idxMap = buildImageIndexMap();
  let totalSwaps = 0;
  const MAX_ITERATIONS = 50;

  // Each group names the stimuliState arrays it holds; swaps write into those arrays.
  const superGroups = [];
  superGroups.push({
    name: 'main_training',
    arrays: [stimuliState.mainItems, stimuliState.trainingDistractors],
  });
  for (let i = 0; i < CONFIG.numICLOrderings; i++) {
    superGroups.push({
      name: `icl_ordering_${i}`,
      arrays: [stimuliState.iclOrderings[i], stimuliState.iclEndDistractors[i]],
    });
  }
  superGroups.push({
    name: 'practice',
    arrays: [stimuliState.practiceItems, stimuliState.practiceEndDistractors],
  });
  superGroups.push({
    name: 'query_only',
    arrays: [stimuliState.queryOnlyPracticeItems],
  });

  /** Every (array, index) position of a group. */
  function slotsOf(group) {
    const slots = [];
    for (const arr of group.arrays) {
      for (let i = 0; i < arr.length; i++) slots.push({ arr, i });
    }
    return slots;
  }

  /** The closest pair of a group: {dist, slotA, slotB}; slotB is the one to move. */
  function worstPair(group) {
    const slots = slotsOf(group);
    let minDist = Infinity;
    let slotA = null;
    let slotB = null;
    for (let i = 0; i < slots.length; i++) {
      for (let j = i + 1; j < slots.length; j++) {
        const d = SIMILARITY_MATRIX[
          idxMap.get(slots[i].arr[slots[i].i].id)
        ][idxMap.get(slots[j].arr[slots[j].i].id)];
        if (d < minDist) {
          minDist = d;
          slotA = slots[i];
          slotB = slots[j];
        }
      }
    }
    return { dist: minDist, slotA, slotB };
  }

  /** The smallest distance within any group. */
  function globalWorstDistance() {
    let m = Infinity;
    for (const g of superGroups) {
      const { dist } = worstPair(g);
      if (dist < m) m = dist;
    }
    return m;
  }

  /** Whether `item` could take position `excludeSlot` in `group` without a close pair. */
  function itemOkInGroup(item, group, excludeSlot) {
    const itemMatrixIdx = idxMap.get(item.id);
    for (const arr of group.arrays) {
      for (let i = 0; i < arr.length; i++) {
        if (arr === excludeSlot.arr && i === excludeSlot.i) continue;
        const otherIdx = idxMap.get(arr[i].id);
        if (SIMILARITY_MATRIX[itemMatrixIdx][otherIdx] < SIMILARITY_THRESHOLD) {
          return false;
        }
      }
    }
    return true;
  }

  function snapshot() {
    return superGroups.map(g => g.arrays.map(arr => [...arr]));
  }

  function restore(snap) {
    for (let g = 0; g < superGroups.length; g++) {
      for (let a = 0; a < superGroups[g].arrays.length; a++) {
        const target = superGroups[g].arrays[a];
        const src = snap[g][a];
        target.length = 0;
        for (const item of src) target.push(item);
      }
    }
  }

  let bestWorstDist = globalWorstDistance();
  let bestSnapshot = snapshot();
  let bestSwaps = 0;

  for (let iter = 0; iter < MAX_ITERATIONS; iter++) {
    let foundViolation = false;

    for (const aIdx of shuffledIndices(superGroups.length)) {
      const groupA = superGroups[aIdx];
      const { dist, slotB: offenderSlot } = worstPair(groupA);
      if (dist >= SIMILARITY_THRESHOLD) continue;
      foundViolation = true;
      const offender = offenderSlot.arr[offenderSlot.i];

      let swapped = false;
      for (const bIdx of shuffledIndices(superGroups.length)) {
        if (bIdx === aIdx) continue;
        const groupB = superGroups[bIdx];
        const bSlots = slotsOf(groupB);
        for (const sIdx of shuffledIndices(bSlots.length)) {
          const candidateSlot = bSlots[sIdx];
          const candidate = candidateSlot.arr[candidateSlot.i];
          if (
            itemOkInGroup(candidate, groupA, offenderSlot) &&
            itemOkInGroup(offender, groupB, candidateSlot)
          ) {
            offenderSlot.arr[offenderSlot.i] = candidate;
            candidateSlot.arr[candidateSlot.i] = offender;
            totalSwaps++;
            swapped = true;
            break;
          }
        }
        if (swapped) break;
      }

      if (!swapped) {
        const partnerSlot = worstPair(groupA).slotA;
        const partner = partnerSlot ? partnerSlot.arr[partnerSlot.i] : null;
        console.warn(
          `ensureGroupDistinctiveness: Could not resolve violation in ${groupA.name}: ` +
          `${partner ? partner.id : '?'} ↔ ${offender.id} (d=${dist.toFixed(4)})`
        );
      }
    }

    const wd = globalWorstDistance();
    if (wd > bestWorstDist) {
      bestWorstDist = wd;
      bestSnapshot = snapshot();
      bestSwaps = totalSwaps;
    }

    if (!foundViolation) break;

    if (iter === MAX_ITERATIONS - 1) {
      console.warn(
        `ensureGroupDistinctiveness: Hit max iterations (${MAX_ITERATIONS}), ` +
        `restoring best state (min distance=${bestWorstDist.toFixed(4)})`
      );
      restore(bestSnapshot);
      return bestSwaps;
    }
  }

  return totalSwaps;
}

/**
 * Assign the session's stimuli: the 80 images are shuffled and cut into roles (in this order:
 * 7 main items, 16 learning distractors, five novel orderings of 7 with 2 end distractors each,
 * 7 practice items, 2 practice end distractors, 3 query-only practice items), similar images
 * are separated, and the trained ordering and the distractor buckets are drawn.
 */
export function initStimuliState() {
  const numItems = CONFIG.numItems;
  const numDistractors = CONFIG.numRankBuckets * CONFIG.distractorsPerRankBucket;
  const numOrderings = CONFIG.numICLOrderings;
  const numEndPerOrdering = CONFIG.numICLEndDistractors;

  const shuffled = shuffledCopy(ALL_IMAGES);
  let idx = 0;
  stimuliState.mainItems = shuffled.slice(idx, idx += numItems);
  stimuliState.trainingDistractors = shuffled.slice(idx, idx += numDistractors);

  stimuliState.iclOrderings = [];
  stimuliState.iclEndDistractors = [];
  for (let i = 0; i < numOrderings; i++) {
    stimuliState.iclOrderings.push(shuffled.slice(idx, idx += numItems));
    stimuliState.iclEndDistractors.push(shuffled.slice(idx, idx += numEndPerOrdering));
  }

  stimuliState.practiceItems = shuffled.slice(idx, idx += numItems);
  stimuliState.practiceEndDistractors = shuffled.slice(idx, idx += CONFIG.numPracticeEndDistractors);
  stimuliState.queryOnlyPracticeItems = shuffled.slice(idx, idx += CONFIG.numQueryOnlyPracticeItems);

  // The roles use every image exactly once.
  if (idx !== ALL_IMAGES.length) {
    throw new Error(
      `initStimuliState: the roles use ${idx} images; there are ${ALL_IMAGES.length}.`
    );
  }

  const similaritySwaps = ensureGroupDistinctiveness();

  // Each novel ordering and its end distractors are saved under its index ('0' to '4').
  const iclOrderingsIdMap = {};
  const iclEndDistractorsIdMap = {};
  for (let i = 0; i < numOrderings; i++) {
    iclOrderingsIdMap[i] = stimuliState.iclOrderings[i].map(s => s.id);
    iclEndDistractorsIdMap[i] = stimuliState.iclEndDistractors[i].map(s => s.id);
  }
  stimuliState.imageAssignments = {
    mainItems: stimuliState.mainItems.map(s => s.id),
    trainingDistractors: stimuliState.trainingDistractors.map(s => s.id),
    iclOrderings: iclOrderingsIdMap,
    iclEndDistractors: iclEndDistractorsIdMap,
    practice: stimuliState.practiceItems.map(s => s.id),
    practiceEndDistractors: stimuliState.practiceEndDistractors.map(s => s.id),
    queryOnlyPractice: stimuliState.queryOnlyPracticeItems.map(s => s.id),
    similaritySwaps,
  };

  stimuliState.trainedOrdering = shuffledCopy(stimuliState.mainItems.map(s => s.id));

  stimuliState.distractorBuckets = generateDistractorBuckets(
    stimuliState.trainingDistractors.map(s => s.id)
  );

  // The sessions in the data made 54 more draws here, for displays that were never shown: a
  // shuffle of 18 context-cue symbols (17 draws), a second ordering of the 7 practice items (6),
  // and shuffles of the 17 and 16 symbols left (16 and 15), 17 + 6 + 16 + 15 = 54. They are
  // drawn and discarded so that every later draw, and so every trial, matches those sessions.
  for (let i = 0; i < 17 + 6 + 16 + 15; i++) Math.random();
}

/**
 * The session's stimuli as saved in the session record (`stimuli`): the image roles, the number
 * of similarity swaps, the trained ordering (as JSON) and the distractor buckets (under the key
 * 0).
 *
 * @returns {object}
 */
export function getStimuliSnapshot() {
  const ia = stimuliState.imageAssignments;
  return {
    image_roles: {
      main_items:                       ia.mainItems,
      training_distractors:             ia.trainingDistractors,
      icl_orderings:                    { ...ia.iclOrderings },
      icl_end_distractors_per_ordering: { ...ia.iclEndDistractors },
      practice:                         ia.practice,
      practice_end_distractors:         ia.practiceEndDistractors,
      query_only_practice:              ia.queryOnlyPractice,
    },
    similarity_swaps:                   ia.similaritySwaps,
    trained_ordering_json:              JSON.stringify(stimuliState.trainedOrdering),
    training_distractor_buckets:        { 0: JSON.parse(JSON.stringify(stimuliState.distractorBuckets)) },
  };
}

/**
 * The stimulus with this ID.
 * @param {string} id
 * @returns {{id: string, label: string, image: string} | undefined}
 */
export function getStimulusById(id) {
  return ensureIdMap().get(id);
}
